"""Command-line interface for the cart pricing helper.

Usage:
    python cart_cli.py --item 2:499 --item 1:52 --discount 5

Every item is QUANTITY:UNIT_CENTS. Amounts are integer cents, and the
discount is a whole percentage between 0 and 100. Invalid input is reported
on stderr and exits with status 2, the same convention argparse uses.
"""

import argparse
import sys

from cart import cart_total, format_cents


def parse_item(text):
    """Parse 'QUANTITY:UNIT_CENTS' into a (quantity, unit_cents) pair.

    Raises ValueError with a readable message when the text is malformed.
    """
    parts = text.split(":")
    if len(parts) != 2:
        raise ValueError(
            f"expected QUANTITY:UNIT_CENTS, got {text!r}"
        )
    quantity_text, unit_text = (part.strip() for part in parts)
    try:
        quantity = int(quantity_text)
        unit_cents = int(unit_text)
    except ValueError:
        raise ValueError(
            f"expected whole numbers in {text!r}"
        ) from None
    if quantity < 1:
        raise ValueError(f"quantity must be at least 1 in {text!r}")
    if unit_cents < 0:
        raise ValueError(f"unit price must not be negative in {text!r}")
    return quantity, unit_cents


def parse_discount(text):
    """Parse a whole-number percentage between 0 and 100."""
    try:
        discount = int(text.strip())
    except ValueError:
        raise ValueError(
            f"discount must be a whole number, got {text!r}"
        ) from None
    if not 0 <= discount <= 100:
        raise ValueError(f"discount must be between 0 and 100, got {discount}")
    return discount


def _item_arg(text):
    try:
        return parse_item(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _discount_arg(text):
    try:
        return parse_discount(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def build_parser():
    parser = argparse.ArgumentParser(
        prog="cart_cli.py",
        description="Total a shopping cart from the command line.",
        epilog="example: python cart_cli.py --item 2:499 --item 1:52 --discount 5",
    )
    parser.add_argument(
        "--item",
        action="append",
        required=True,
        type=_item_arg,
        metavar="QTY:CENTS",
        help="line item as QUANTITY:UNIT_CENTS; repeat for each item",
    )
    parser.add_argument(
        "--discount",
        default=0,
        type=_discount_arg,
        metavar="PERCENT",
        help="whole-number discount percentage from 0 to 100 (default: 0)",
    )
    return parser


def main(argv=None):
    """Run the CLI and return the process exit status."""
    parser = build_parser()
    args = parser.parse_args(argv)
    total_cents = cart_total(args.item, args.discount)
    print(format_cents(total_cents))
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""Tests for cart_cli.py, including its input validation."""

import io
import unittest
from contextlib import redirect_stderr, redirect_stdout

from cart_cli import main, parse_discount, parse_item


class ParseItemTests(unittest.TestCase):
    def test_parses_pair(self):
        self.assertEqual(parse_item("3:250"), (3, 250))

    def test_tolerates_surrounding_spaces(self):
        self.assertEqual(parse_item(" 2 : 499 "), (2, 499))

    def test_rejects_missing_separator(self):
        with self.assertRaisesRegex(ValueError, "QUANTITY:UNIT_CENTS"):
            parse_item("3250")

    def test_rejects_extra_separator(self):
        with self.assertRaisesRegex(ValueError, "QUANTITY:UNIT_CENTS"):
            parse_item("1:2:3")

    def test_rejects_non_numeric(self):
        with self.assertRaisesRegex(ValueError, "whole numbers"):
            parse_item("two:250")

    def test_rejects_zero_quantity(self):
        with self.assertRaisesRegex(ValueError, "at least 1"):
            parse_item("0:250")

    def test_rejects_negative_quantity(self):
        with self.assertRaisesRegex(ValueError, "at least 1"):
            parse_item("-1:250")

    def test_rejects_negative_price(self):
        with self.assertRaisesRegex(ValueError, "must not be negative"):
            parse_item("1:-250")

    def test_rejects_empty_text(self):
        with self.assertRaises(ValueError):
            parse_item("")


class ParseDiscountTests(unittest.TestCase):
    def test_accepts_bounds(self):
        self.assertEqual(parse_discount("0"), 0)
        self.assertEqual(parse_discount("100"), 100)

    def test_accepts_typical_value(self):
        self.assertEqual(parse_discount("5"), 5)

    def test_rejects_below_zero(self):
        with self.assertRaisesRegex(ValueError, "between 0 and 100"):
            parse_discount("-1")

    def test_rejects_above_hundred(self):
        with self.assertRaisesRegex(ValueError, "between 0 and 100"):
            parse_discount("101")

    def test_rejects_non_integer(self):
        with self.assertRaisesRegex(ValueError, "whole number"):
            parse_discount("1.5")


class MainTests(unittest.TestCase):
    def run_cli(self, argv):
        out, err = io.StringIO(), io.StringIO()
        with redirect_stdout(out), redirect_stderr(err):
            status = main(argv)
        return status, out.getvalue(), err.getvalue()

    def test_prints_discounted_total(self):
        status, out, _ = self.run_cli(["--item", "2:499", "--item", "1:52", "--discount", "5"])
        self.assertEqual(status, 0)
        self.assertEqual(out.strip(), "9.97")

    def test_defaults_to_no_discount(self):
        status, out, _ = self.run_cli(["--item", "1:250"])
        self.assertEqual(status, 0)
        self.assertEqual(out.strip(), "2.50")

    def test_bad_item_exits_two_with_message(self):
        with self.assertRaises(SystemExit) as caught:
            self.run_cli(["--item", "0:250"])
        self.assertEqual(caught.exception.code, 2)

    def test_out_of_range_discount_exits_two(self):
        with self.assertRaises(SystemExit) as caught:
            self.run_cli(["--item", "1:250", "--discount", "150"])
        self.assertEqual(caught.exception.code, 2)

    def test_missing_item_exits_two(self):
        with self.assertRaises(SystemExit) as caught:
            self.run_cli([])
        self.assertEqual(caught.exception.code, 2)


if __name__ == "__main__":
    unittest.main()
